import React from "react";
import { useAppContext, actions } from "../context/AppContext";

const SettingsPanel = () => {
  const { state, dispatch } = useAppContext();

  if (!state.ui.showSettings) {
    return null;
  }

  const handleHighlightColorChange = (event) => {
    dispatch(actions.setHighlightColor(event.target.value));
  };

  const handleThemeChange = (theme) => {
    dispatch(actions.setTheme(theme));
  };

  const handleAnimationSpeedChange = (event) => {
    const speed = parseFloat(event.target.value);
    dispatch(actions.setAnimationSpeed(speed));
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50 backdrop-blur-sm">
      <div className="bg-space-purple bg-opacity-95 text-white p-8 rounded-2xl shadow-2xl max-w-md w-full mx-4 max-h-[80vh] overflow-y-auto">
        {/* Header */}
        <div className="flex items-center justify-between mb-6">
          <h2 className="text-2xl font-bold">Settings</h2>
          <button
            onClick={() => dispatch(actions.toggleSettings())}
            className="text-gray-300 hover:text-white transition-colors"
            title="Close Settings"
          >
            <svg
              className="w-6 h-6"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M6 18L18 6M6 6l12 12"
              />
            </svg>
          </button>
        </div>

        <div className="space-y-6">
          {/* Theme Settings */}
          <div>
            <h3 className="text-lg font-semibold text-blue-300 mb-4">Theme</h3>
            <div className="grid grid-cols-2 gap-3">
              {[
                { key: "dark", label: "Dark Space", bg: "bg-gray-900" },
                { key: "light", label: "Light", bg: "bg-gray-100" },
              ].map(({ key, label, bg }) => (
                <button
                  key={key}
                  onClick={() => handleThemeChange(key)}
                  className={`p-4 rounded-lg border-2 transition-all duration-200 ${
                    state.ui.theme === key
                      ? "border-blue-500 bg-blue-600 bg-opacity-20"
                      : "border-gray-600 hover:border-gray-500"
                  }`}
                >
                  <div className={`w-full h-8 ${bg} rounded mb-2`}></div>
                  <span className="text-sm">{label}</span>
                </button>
              ))}
            </div>
          </div>

          {/* Animation Settings */}
          <div>
            <h3 className="text-lg font-semibold text-blue-300 mb-4">
              Animation
            </h3>

            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <span className="text-sm">Enable Animations</span>
                <button
                  onClick={() => dispatch(actions.toggleAnimation())}
                  className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${
                    state.animation.isPlaying ? "bg-blue-600" : "bg-gray-600"
                  }`}
                >
                  <span
                    className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
                      state.animation.isPlaying
                        ? "translate-x-6"
                        : "translate-x-1"
                    }`}
                  />
                </button>
              </div>

              <div>
                <label className="block text-sm mb-2">
                  Animation Speed: {state.animation.speed.toFixed(1)}x
                </label>
                <input
                  type="range"
                  min="0.1"
                  max="3"
                  step="0.1"
                  value={state.animation.speed}
                  onChange={handleAnimationSpeedChange}
                  className="w-full h-2 bg-gray-700 rounded-lg appearance-none cursor-pointer slider"
                />
              </div>
            </div>
          </div>

          {/* Visual Settings */}
          <div>
            <h3 className="text-lg font-semibold text-blue-300 mb-4">Visual</h3>

            <div className="space-y-4">
              <div>
                <label className="block text-sm mb-2">
                  Country Highlight Color
                </label>
                <div className="flex items-center space-x-3">
                  <input
                    type="color"
                    value={state.countries.highlightColor}
                    onChange={handleHighlightColorChange}
                    className="w-12 h-8 rounded border border-gray-600 cursor-pointer"
                  />
                  <span className="text-sm font-mono">
                    {state.countries.highlightColor}
                  </span>
                </div>
              </div>

              <div className="flex items-center justify-between">
                <span className="text-sm">Show Country Borders</span>
                <button
                  onClick={() => dispatch(actions.toggleBorders())}
                  className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${
                    state.countries.showBorders ? "bg-blue-600" : "bg-gray-600"
                  }`}
                >
                  <span
                    className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
                      state.countries.showBorders
                        ? "translate-x-6"
                        : "translate-x-1"
                    }`}
                  />
                </button>
              </div>
            </div>
          </div>

          {/* Performance Settings */}
          <div>
            <h3 className="text-lg font-semibold text-blue-300 mb-4">
              Performance
            </h3>

            <div className="space-y-3">
              <div className="bg-gray-800 bg-opacity-50 p-3 rounded-lg">
                <div className="text-sm text-gray-300 mb-1">WebGL Status</div>
                <div className="text-green-400 font-medium">✓ Enabled</div>
              </div>

              <div className="bg-gray-800 bg-opacity-50 p-3 rounded-lg">
                <div className="text-sm text-gray-300 mb-1">
                  Hardware Acceleration
                </div>
                <div className="text-green-400 font-medium">✓ Active</div>
              </div>

              <div className="bg-gray-800 bg-opacity-50 p-3 rounded-lg">
                <div className="text-sm text-gray-300 mb-1">Memory Usage</div>
                <div className="text-blue-400 font-medium">~50MB</div>
              </div>
            </div>
          </div>

          {/* Export Settings */}
          <div>
            <h3 className="text-lg font-semibold text-blue-300 mb-4">Export</h3>

            <div className="space-y-3">
              <button
                onClick={() => {
                  // Export screenshot
                  console.log("Export screenshot");
                }}
                className="w-full bg-green-600 hover:bg-green-700 text-white py-2 px-4 rounded-lg transition-colors text-sm"
              >
                📸 Export Screenshot
              </button>

              <button
                onClick={() => {
                  // Export video
                  console.log("Export video");
                }}
                className="w-full bg-purple-600 hover:bg-purple-700 text-white py-2 px-4 rounded-lg transition-colors text-sm"
              >
                🎥 Export Video
              </button>

              <button
                onClick={() => {
                  // Export settings
                  const settings = JSON.stringify(state, null, 2);
                  const blob = new Blob([settings], {
                    type: "application/json",
                  });
                  const url = URL.createObjectURL(blob);
                  const a = document.createElement("a");
                  a.href = url;
                  a.download = "earth-viewer-settings.json";
                  a.click();
                  URL.revokeObjectURL(url);
                }}
                className="w-full bg-blue-600 hover:bg-blue-700 text-white py-2 px-4 rounded-lg transition-colors text-sm"
              >
                💾 Export Settings
              </button>
            </div>
          </div>
        </div>

        {/* Footer */}
        <div className="mt-8 pt-4 border-t border-gray-600 text-center">
          <p className="text-xs text-gray-400">
            Earth Viewer v2.0 • React + Three.js
          </p>
        </div>
      </div>
    </div>
  );
};

export default SettingsPanel;
